<script setup>
import {computed,ref,reactive,onMounted,onUnmounted} from 'vue'
import {api} from './api'
import NetworkSettings from './NetworkSettings.vue'
const props=defineProps({page:String,token:String,language:String})
const emit=defineEmits(['dirty'])
const tr=(ru,uz,en)=>({ru,uz,en}[props.language]||ru)
const titles={diagnostics:['Диагностика оборудования','Uskuna diagnostikasi','Hardware diagnostics'],connections:['Подключение','Ulanish','Connections'],maintenance:['Обслуживание','Xizmat ko‘rsatish','Maintenance']}
const outputNames={water:['Вода','Suv','Water'],osmos:['Осмос','Osmos','Osmos'],nano:['Нано','Nano','Nano'],foam:['Пена','Ko‘pik','Foam'],wax:['Воск','Mum','Wax'],chem:['Химия','Kimyo','Chemistry'],vacuum:['Пылесос','Changyutgich','Vacuum'],air:['Воздух','Havo','Air']}
const request=(path,options={})=>api('/api/admin/'+path,{token:props.token,...options})
const post=(path,body={})=>request(path,{method:'POST',body:JSON.stringify(body)})
const snapshot=ref(null),error=ref(''),pollError=ref(''),notice=ref(''),busy=ref(false),refreshing=ref(false),updated=ref(0),now=ref(Date.now()),dirty=ref(false),networkDirty=ref(false),confirmation=ref(null)
const io=computed(()=>snapshot.value?.io.available?snapshot.value.io.data:null),rfid=computed(()=>snapshot.value?.rfid.available?snapshot.value.rfid.data:null),config=computed(()=>snapshot.value?.configuration.available?snapshot.value.configuration.data:null)
const stale=computed(()=>!updated.value || now.value-updated.value>6500 || !!pollError.value)
const idle=computed(()=>{const s=snapshot.value?.state;return !!s&&!stale.value&&!s.activeMode&&!s.requestedOutput&&!s.armedMode&&!s.activeSessionId&&!Number(s.creditSum)&&!Number(s.vipRemainingSeconds)})
const canTest=computed(()=>idle.value&&io.value?.modbus_ok&&Object.keys(io.value.outputs||{}).length===8&&!Object.values(io.value.outputs||{}).some(Boolean))
const name=k=>outputNames[k]?tr(...outputNames[k]):k
const n=v=>Number(v||0).toLocaleString(props.language==='ru'?'ru-RU':'en-US')
const stamp=v=>v?new Date(v).toLocaleString('ru-RU',{timeZone:'Asia/Tashkent'}):'—'
function mark(){dirty.value=true;notice.value='';emit('dirty',true)}
function networkChanged(value){networkDirty.value=value;emit('dirty',dirty.value||value)}
function clean(){dirty.value=false;emit('dirty',networkDirty.value)}
async function refresh(){if(refreshing.value)return;refreshing.value=true;try{snapshot.value=await request('diagnostics',{signal:AbortSignal.timeout(6000)});updated.value=Date.now();now.value=Date.now();pollError.value=''}catch(e){pollError.value=e.message}finally{refreshing.value=false}}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
const connection=ref(null)
const form=reactive({site_code:'',post_no:1,gateway_url:'',site_token:'',license_enabled:false,click_enabled:false,click_min_amount_sum:1000,click_max_amount_sum:10000000,sync_interval_seconds:43200,grace_seconds:604800})
function fillConnection(data){connection.value=data;const l=data.license_settings,c=data.click_settings;Object.assign(form,{site_code:l.site_code||'',post_no:l.post_no||1,gateway_url:l.gateway_url||c.gateway_url||'',site_token:'',license_enabled:!!l.enabled,click_enabled:!!c.enabled,click_min_amount_sum:c.min_amount_sum,click_max_amount_sum:c.max_amount_sum,sync_interval_seconds:l.sync_interval_seconds,grace_seconds:l.grace_seconds})}
async function loadConnection(){fillConnection(await request('install/status'))}
const events=ref([]),level=ref('all'),hasMore=ref(false),recovery=ref([]),pulseValue=ref(1000),offlineCode=ref('')
async function loadEvents(older=false){const before=older?(events.value.at(-1)?.id||0):0;const result=await request('service/events?'+new URLSearchParams({level:level.value,before,limit:30}));events.value=older?[...events.value,...result.events]:result.events;hasMore.value=result.has_more}
async function loadMaintenance(){await Promise.all([loadEvents(),request('service/recovery').then(r=>recovery.value=r.credits),loadConnection()]);pulseValue.value=snapshot.value?.parameters.billPulseSum||1000}
async function act(){const action=confirmation.value; if(!action)return;
 if(action.type==='test'){await post('service/outputs/'+action.name+'/test',{confirmation:action.name});notice.value=tr('Тест завершён, выключение подтверждено','Sinov tugadi, o‘chirilgani tasdiqlandi','Test finished; OFF confirmed')}
 if(action.type==='off'){await post('service/all-off');notice.value=tr('Все выходы подтвердили OFF. Включена WEB PAUSE.','Barcha chiqishlar OFF. WEB PAUSE yoqildi.','All outputs confirmed OFF. WEB PAUSE applied.')}
 if(action.type==='connection'){const result=await post('install/apply',{...form,reset_runtime_data:false});fillConnection(result);clean();notice.value=tr('Настройки подключения сохранены','Ulanish sozlamalari saqlandi','Connection settings saved')}
 if(action.type==='pulse'){await post('service/money-input',{bill_pulse_sum:pulseValue.value});dirty.value=!!offlineCode.value;emit('dirty',dirty.value||networkDirty.value);notice.value=tr('Стоимость импульса сохранена','Impuls qiymati saqlandi','Pulse value saved')}
 if(action.type==='real'){await post('service/real-inputs');notice.value=tr('Используются реальные входы','Haqiqiy kirishlar ishlatilmoqda','Real inputs restored')}
 if(action.type==='offline'){await post('license/offline-code',{code:offlineCode.value});offlineCode.value='';dirty.value=pulseValue.value!==snapshot.value?.parameters.billPulseSum;emit('dirty',dirty.value||networkDirty.value);await loadConnection();notice.value=tr('Код применён','Kod qo‘llandi','Code applied')}
 if(action.type==='sync-license'){await post('license/sync');await loadConnection();notice.value=tr('Состояние лицензии обновлено','Litsenziya holati yangilandi','License status refreshed')}
 if(action.type==='sync-click'){const r=await post('click/sync');notice.value=tr('Синхронизация Click завершена','Click sinxronlash tugadi','Click synchronization completed')+' · '+(r.credited||0)}
 confirmation.value=null;await refresh();if(props.page==='maintenance')await loadEvents()
}
async function exportDiagnostics(){await refresh();if(stale.value)throw Error(tr('Нет свежих данных','Yangi ma’lumot yo‘q','No fresh data'));const copy=JSON.parse(JSON.stringify(snapshot.value,(key,value)=>/uid|password|token|secret/i.test(key)?undefined:value));delete copy.state.activeSessionCardUid;if(copy.rfid.data){delete copy.rfid.data.latest;delete copy.rfid.data.last_seen_at}const url=URL.createObjectURL(new Blob([JSON.stringify(copy,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='sammoy-diagnostics-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const confirmTitle=computed(()=>{const type=confirmation.value?.type;return type==='test'?tr('Включить на 1 секунду: ','1 soniyaga yoqilsin: ','Turn on for 1 second: ')+name(confirmation.value.name):type==='off'?tr('Выключить все выходы?','Barcha chiqishlar o‘chirilsinmi?','Switch all outputs off?'):tr('Применить изменение?','O‘zgarish qo‘llansinmi?','Apply this change?')})
let timer;onMounted(()=>{run(async()=>{await refresh();if(props.page==='connections')await loadConnection();if(props.page==='maintenance')await loadMaintenance()});timer=setInterval(()=>{now.value=Date.now();if(!document.hidden&&!busy.value)refresh()},2000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="owner-page admin-page">
<div class="heading"><h1>{{ tr(...titles[page]) }}</h1><p>{{ tr('Состояние поста и инструменты администратора','Post holati va administrator vositalari','Station status and administrator tools') }}</p></div>
<div v-if="error" class="message error" role="alert">{{ error }}</div><div v-if="pollError" class="message error" role="alert">{{ tr('Данные недоступны: ','Ma’lumot mavjud emas: ','Data unavailable: ') }}{{ pollError }}</div><div v-if="notice" class="message success" role="status">{{ notice }}</div>
<div class="toolbar"><p>{{ stale?tr('Нет свежих данных','Yangi ma’lumot yo‘q','No fresh data'):tr('Обновлено','Yangilandi','Updated')+' '+stamp(updated) }} · {{ tr('Автообновление каждые 2 секунды','Har 2 soniyada yangilanadi','Refreshes every 2 seconds') }}</p><div><button class="quiet" :disabled="busy || refreshing" @click="refresh">{{ tr('Обновить','Yangilash','Refresh') }}</button><button class="quiet danger-button" :disabled="busy" @click="confirmation={type:'off'}">{{ tr('Все выходы OFF','Barcha chiqishlar OFF','All outputs OFF') }}</button></div></div>
<template v-if="page==='diagnostics'">
<div class="metrics"><section class="card metric"><p>Modbus</p><strong :class="{'good-text':!stale&&io?.modbus_ok,'bad-text':!stale&&!io?.modbus_ok}">{{ stale?'—':io?.modbus_ok?tr('На связи','Ulangan','Online'):tr('Нет связи','Aloqa yo‘q','Offline') }}</strong><small>{{ config?.transport.device || '—' }} · {{ config?.transport.baud_rate || '—' }}</small></section><section class="card metric"><p>PN532</p><strong>{{ stale?'—':rfid?.online?tr('На связи','Ulangan','Online'):tr('Нет связи','Aloqa yo‘q','Offline') }}</strong><small>I²C {{ rfid?.bus??'—' }} · {{ rfid?.firmware||'—' }}</small></section><section class="card metric"><p>{{ tr('Импульсы NV9','NV9 impulslari','NV9 pulses') }}</p><strong>{{ stale?'—':n(io?.nv9_pulses) }}</strong><small>{{ tr('С запуска io-helper','io-helper ishga tushgandan','Since io-helper start') }}</small></section><section class="card metric"><p>{{ tr('Баланс, сум','Balans, so‘m','Balance, sum') }}</p><strong>{{ snapshot?n(snapshot.state.creditSum):'—' }}</strong><small>{{ snapshot?.state.phase || '—' }}</small></section></div>
<div class="grid"><section class="card"><div class="card-head"><h2>{{ tr('Цифровые входы','Raqamli kirishlar','Digital inputs') }}</h2></div><div class="table-wrap"><table><thead><tr><th>{{ tr('Клемма','Klemma','Terminal') }}</th><th>{{ tr('Назначение','Vazifa','Function') }}</th><th>{{ tr('Уровень','Daraja','Raw level') }}</th><th>{{ tr('Сигнал','Signal','Signal') }}</th></tr></thead><tbody><tr v-for="i in config?.inputs||[]" :key="i.name"><th>DI{{ i.address+1 }}</th><td>{{ i.name==='total_stop'?tr('Курок / Total Stop','Tugma / Total Stop','Trigger / Total Stop'):i.name }}</td><td>{{ stale?'—':io?.raw_inputs?.[i.address]??'—' }}</td><td><span class="status-pill" :class="{positive:!stale&&io?.inputs?.[i.name]}">{{ stale?'—':io?.inputs?.[i.name]?tr('Активен','Faol','Active'):tr('Неактивен','Faol emas','Inactive') }}</span></td></tr></tbody></table></div><p class="content muted">{{ tr('DI3: активный уровень 0. Нажатие курка видно без включения программы.','DI3: faol daraja 0. Tugma bosilishi dastur yoqilmasdan ko‘rinadi.','DI3 is active low. Trigger activity is visible without starting a program.') }}</p></section>
<section class="card"><div class="card-head"><h2>{{ tr('Выходы реле','Rele chiqishlari','Relay outputs') }}</h2></div><div class="table-wrap"><table><thead><tr><th>DO</th><th>{{ tr('Программа','Dastur','Program') }}</th><th>{{ tr('Состояние','Holat','State') }}</th><th>{{ tr('Проверка','Tekshirish','Test') }}</th></tr></thead><tbody><tr v-for="o in config?.outputs||[]" :key="o.name"><th>{{ o.address+1 }}</th><td>{{ name(o.name) }}</td><td><span class="status-pill" :class="{positive:!stale&&io?.outputs?.[o.name]}">{{ stale?'—':io?.outputs?.[o.name]?'ON':'OFF' }}</span></td><td><button class="quiet" :disabled="busy || !canTest" @click="confirmation={type:'test',name:o.name}">{{ tr('Тест 1 с','Sinov 1 s','Test 1 s') }}</button></td></tr></tbody></table></div><p v-if="!idle" class="content muted">{{ tr('Тесты доступны после завершения сеанса и сохранения остатка клиента.','Sinovlar seans tugagach va mijoz qoldig‘i saqlangach mumkin.','Tests are available after the session ends and the remaining credit is preserved.') }}</p></section></div>
<div class="grid"><section class="card content"><h2>PN532 / RFID</h2><dl class="detail-list"><div><dt>{{ tr('Последняя карта','Oxirgi karta','Last card') }}</dt><dd>{{ rfid?.latest?.uid||'—' }}</dd></div><div><dt>{{ tr('Время чтения','O‘qish vaqti','Read time') }}</dt><dd>{{ stamp(rfid?.latest?.seen_at) }}</dd></div><div><dt>{{ tr('Карта у считывателя','O‘quvchida karta','Card present') }}</dt><dd>{{ rfid?.present?tr('Да','Ha','Yes'):tr('Нет','Yo‘q','No') }}</dd></div><div><dt>{{ tr('Ошибка','Xato','Error') }}</dt><dd>{{ rfid?.last_error||'—' }}</dd></div></dl></section><section class="card content"><h2>Radxa</h2><dl class="detail-list"><div><dt>{{ tr('Температура','Harorat','Temperature') }}</dt><dd>{{ snapshot?.system.temperature_c??'—' }} °C</dd></div><div><dt>{{ tr('Свободно на диске','Diskda bo‘sh joy','Free disk') }}</dt><dd>{{ snapshot?((snapshot.system.disk_free_bytes/1024**3).toFixed(1)):'—' }} GB</dd></div><div><dt>NV9 GPIO</dt><dd>{{ config?.bill_acceptor.gpio_chip }} · {{ config?.bill_acceptor.gpio_line }}</dd></div><div><dt>{{ tr('Слушатель NV9','NV9 tinglovchisi','NV9 listener') }}</dt><dd>{{ config?.nv9_listener_alive?tr('Работает','Ishlayapti','Running'):tr('Нет данных','Ma’lumot yo‘q','Unknown') }}</dd></div></dl></section></div>
</template>
<template v-if="page==='connections'">
<NetworkSettings :token="token" :language="language" :idle="idle" @dirty="networkChanged" />
<form v-if="connection" class="card content" @input="mark" @change="mark" @submit.prevent="confirmation={type:'connection'}"><h2>{{ tr('Сервер и номер поста','Server va post raqami','Server and station identity') }}</h2><p class="muted">{{ tr('Пустое поле ключа сохраняет действующий ключ. Пароли и ключи не отображаются.','Kalit maydoni bo‘sh bo‘lsa, joriy kalit saqlanadi. Parol va kalitlar ko‘rsatilmaydi.','Leave the key empty to keep the existing key. Passwords and keys are not displayed.') }}</p><div class="fields"><label>{{ tr('Код мойки','Yuvish kodi','Site code') }}<input v-model.trim="form.site_code" required maxlength="80" /></label><label>{{ tr('Номер поста','Post raqami','Station number') }}<input v-model.number="form.post_no" type="number" min="1" max="100" required /></label><label>{{ tr('Адрес сервера','Server manzili','Server address') }}<input v-model.trim="form.gateway_url" type="url" required maxlength="300" /></label><label>{{ tr('Новый ключ мойки','Yangi yuvish kaliti','New site key') }}<input v-model="form.site_token" type="password" autocomplete="off" maxlength="300" /></label><label class="check"><input v-model="form.license_enabled" type="checkbox" />{{ tr('Контроль лицензии','Litsenziya nazorati','License enforcement') }}</label><label class="check"><input v-model="form.click_enabled" type="checkbox" />Click</label><label>{{ tr('Минимальный платёж Click','Click minimal to‘lov','Click minimum amount') }}<input v-model.number="form.click_min_amount_sum" type="number" min="1" max="10000000" required /></label><label>{{ tr('Максимальный платёж Click','Click maksimal to‘lov','Click maximum amount') }}<input v-model.number="form.click_max_amount_sum" type="number" :min="form.click_min_amount_sum" max="100000000" required /></label><label>{{ tr('Интервал синхронизации, сек','Sinxronlash oralig‘i, soniya','Sync interval, seconds') }}<input v-model.number="form.sync_interval_seconds" type="number" min="300" max="86400" required /></label><label>{{ tr('Допуск без связи, сек','Aloqasiz ruxsat, soniya','Offline grace, seconds') }}<input v-model.number="form.grace_seconds" type="number" min="0" max="2592000" required /></label></div><div class="actions" style="margin-top:24px"><button class="primary" :disabled="busy || !dirty || !idle">{{ tr('Сохранить подключение','Ulanishni saqlash','Save connection') }}</button></div><p v-if="!idle" class="muted">{{ tr('Сначала завершите текущий сеанс.','Avval joriy seansni yakunlang.','Finish the current session first.') }}</p></form>
</template>
<template v-if="page==='maintenance'">
<div class="grid"><section class="card content"><h2>{{ tr('Сервисные действия','Xizmat amallari','Service actions') }}</h2><p class="muted">{{ tr('Диагностический файл не содержит паролей, ключей и последнего UID карты.','Diagnostika faylida parol, kalit va oxirgi karta UID yo‘q.','The diagnostics file excludes passwords, keys and the last card UID.') }}</p><div class="actions"><button class="quiet" :disabled="busy" @click="run(exportDiagnostics)">{{ tr('Скачать диагностику','Diagnostikani yuklab olish','Download diagnostics') }}</button><button class="quiet" :disabled="busy || !idle" @click="confirmation={type:'real'}">{{ tr('Вернуть реальные входы','Haqiqiy kirishlarga qaytish','Restore real inputs') }}</button></div><p class="muted">{{ tr('Режим входов','Kirishlar rejimi','Input mode') }}: {{ Object.values(snapshot?.simulation||{}).every(v=>v===null||v===false)?tr('Реальное оборудование','Haqiqiy uskuna','Real hardware'):tr('Есть тестовые входы','Sinov kirishlari mavjud','Test inputs enabled') }}</p></section>
<form class="card content" @submit.prevent="confirmation={type:'pulse'}" @input="mark"><h2>NV9</h2><p class="muted">{{ tr('Стоимость одного импульса купюроприёмника. Тарифы программ сохраняются.','Banknota qabul qilgichning bitta impulsi qiymati. Dastur tariflari saqlanadi.','Value of one bill acceptor pulse. Program tariffs are preserved.') }}</p><label>{{ tr('Сум за импульс','Bir impuls uchun so‘m','Sum per pulse') }}<input v-model.number="pulseValue" type="number" min="1" max="10000000" required /></label><button class="primary" style="margin-top:20px" :disabled="busy || !idle || !dirty">{{ tr('Сохранить','Saqlash','Save') }}</button></form></div>
<section v-if="connection" class="card content"><h2>{{ tr('Лицензия и Click','Litsenziya va Click','License and Click') }}</h2><dl class="detail-list"><div><dt>{{ tr('Состояние лицензии','Litsenziya holati','License state') }}</dt><dd>{{ connection.license.state || '—' }}</dd></div><div><dt>{{ tr('Действует до','Amal qilish muddati','Valid until') }}</dt><dd>{{ stamp(connection.license.valid_until) }}</dd></div><div><dt>{{ tr('Последняя связь','Oxirgi aloqa','Last connection') }}</dt><dd>{{ stamp(connection.license.last_success_at) }}</dd></div></dl><div class="actions"><button class="quiet" :disabled="busy || !idle || !connection.license_settings.site_code" @click="confirmation={type:'sync-license'}">{{ tr('Обновить лицензию','Litsenziyani yangilash','Refresh license') }}</button><button class="quiet" :disabled="busy || !connection.click_settings.enabled" @click="confirmation={type:'sync-click'}">{{ tr('Синхронизировать Click','Clickni sinxronlash','Synchronize Click') }}</button></div><form @input="mark" @submit.prevent="confirmation={type:'offline'}" style="margin-top:24px"><label>{{ tr('Офлайн-код лицензии','Litsenziyaning oflayn kodi','Offline license code') }}<input v-model.trim="offlineCode" minlength="20" maxlength="1200" required autocomplete="off" /></label><button class="quiet" style="margin-top:16px" :disabled="busy || !idle || !offlineCode">{{ tr('Применить код','Kodni qo‘llash','Apply code') }}</button></form></section>
<section class="card"><div class="card-head"><h2>{{ tr('Сохранённые остатки после отключения','Elektr uzilgandan keyin saqlangan qoldiqlar','Credit preserved after outages') }}</h2></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>{{ tr('Сеанс','Seans','Session') }}</th><th>{{ tr('Сумма','Summa','Amount') }}</th><th>{{ tr('Дата','Sana','Date') }}</th></tr></thead><tbody><tr v-for="r in recovery" :key="r.id"><td>{{ r.id }}</td><td>{{ r.wash_session_id }}</td><td>{{ n(r.amount_sum) }}</td><td>{{ stamp(r.created_at) }}</td></tr></tbody></table></div><p v-if="!recovery.length" class="empty">{{ tr('Невостребованных остатков нет','Talab qilinmagan qoldiqlar yo‘q','No unclaimed credit') }}</p></section>
<section class="card"><div class="card-head admin-section-head"><h2>{{ tr('Журнал событий','Voqealar jurnali','Event log') }}</h2><div class="actions"><label>{{ tr('Уровень','Daraja','Level') }}<select v-model="level" :disabled="busy" @change="run(()=>loadEvents())"><option value="all">{{ tr('Все','Barchasi','All') }}</option><option value="info">Info</option><option value="warning">Warning</option><option value="error">Error</option><option value="critical">Critical</option></select></label><button class="quiet" :disabled="busy" @click="run(()=>loadEvents())">{{ tr('Обновить журнал','Jurnalni yangilash','Refresh log') }}</button></div></div><div class="table-wrap"><table><thead><tr><th>{{ tr('Время','Vaqt','Time') }}</th><th>{{ tr('Уровень','Daraja','Level') }}</th><th>{{ tr('Событие','Voqea','Event') }}</th><th>{{ tr('Описание','Tavsif','Description') }}</th></tr></thead><tbody><tr v-for="e in events" :key="e.id"><td>{{ stamp(e.created_at) }}</td><td>{{ e.level }}</td><td>{{ e.event_type }}</td><td>{{ e.message }}</td></tr></tbody></table></div><p v-if="!events.length" class="empty">{{ tr('Событий нет','Voqealar yo‘q','No events') }}</p><div class="content actions end"><button v-if="hasMore" class="quiet" :disabled="busy" @click="run(()=>loadEvents(true))">{{ tr('Показать более ранние','Oldingilarini ko‘rsatish','Load earlier events') }}</button></div></section>
</template>
<div v-if="confirmation" class="confirm-backdrop"><section class="card confirm-dialog" role="alertdialog" aria-modal="true"><h2>{{ confirmTitle }}</h2><p v-if="confirmation.type==='test'">{{ tr('Будет включено реальное оборудование. Убедитесь, что пост свободен. Через 1 секунду io-helper выключит выход.','Haqiqiy uskuna yoqiladi. Post bo‘shligini tekshiring. 1 soniyadan keyin io-helper chiqishni o‘chiradi.','Real equipment will switch on. Ensure the station is clear. io-helper switches it off after 1 second.') }}</p><p v-if="confirmation.type==='off'">{{ tr('Применяется WEB PAUSE по правилам sammoy2. Средства клиента не обнуляются.','sammoy2 qoidalari bo‘yicha WEB PAUSE qo‘llanadi. Mijoz mablag‘i nolga tushirilmaydi.','Applies WEB PAUSE under sammoy2 rules. Client credit is not reset.') }}</p><div v-if="error" class="message error">{{ error }}</div><div class="actions"><button class="quiet" :disabled="busy" @click="confirmation=null">{{ tr('Отмена','Bekor qilish','Cancel') }}</button><button class="primary" :disabled="busy || (confirmation.type==='test'&&!canTest)" @click="run(act)">{{ busy?tr('Выполняется…','Bajarilmoqda…','Working…'):tr('Подтвердить','Tasdiqlash','Confirm') }}</button></div></section></div>
</section></template>
